/* ─── Helpers ────────────────────────────────────── */
const num = (v) => {
  const n = parseFloat(v);
  return isNaN(n) ? 0 : n;
};
/* Read a numeric field by normalised API name (case / underscore / spacing
   insensitive), so "Total_Pullet_Cost", "Total Pullet Cost" and
   "Total_Pullets_Cost" all resolve. Returns null when no such field exists. */
const numByNormName = (rec, ...needles) => {
  if (!rec) return null;
  for (const key of Object.keys(rec)) {
    const norm = key.toLowerCase().replace(/[^a-z]/g, "");
    if (!needles.includes(norm)) continue;
    const raw = rec[key];
    const val = raw && typeof raw === "object" ? (raw.zc_display_value ?? raw.display_value ?? "") : raw;
    if (val === null || val === undefined || val === "") continue;
    const n = parseFloat(String(val).replace(/,/g, ""));
    if (!isNaN(n)) return n;
  }
  return null;
};
const fv = (rec, f) => {
  if (!rec || !f) return null;
  const v = rec[f];
  if (!v) return null;
  return typeof v === "object"
    ? v.zc_display_value || v.display_value || v.Name || null
    : v;
};

/* Numeric field reader — 0 stays 0 and does NOT fall through to the next
   field name. Use this anywhere a `fv(a) || fv(b)` chain reads a number. */
const numField = (rec, ...names) => {
  for (const n of names) {
    const raw = rec?.[n];
    if (raw === null || raw === undefined || raw === "") continue;
    const val = typeof raw === "object"
      ? (raw.zc_display_value ?? raw.display_value ?? "")
      : raw;
    const parsed = parseFloat(val);
    if (!isNaN(parsed)) return parsed;
  }
  return 0;
};

const displayVal = (v) => {
  if (v === null || v === undefined) return "";
  if (typeof v === "object")
    return (v.zc_display_value ?? v.display_value ?? v.name ?? "").toString();
  return v.toString();
};
const fmtN = (n, d = 0) =>
  n == null
    ? "—"
    : Number(n).toLocaleString("en-US", {
      minimumFractionDigits: d,
      maximumFractionDigits: d,
    });


const fmtCur = (n) => {
  if (!n) return "GHC 0";
  const sign = n < 0 ? "-" : "";
  const abs = Math.abs(n);
  if (abs >= 1e9) return `GHC ${sign}${(abs / 1e9).toFixed(1)}B`;
  if (abs >= 1e6) return `GHC ${sign}${(abs / 1e6).toFixed(1)}M`;
  if (abs >= 1e3) return `GHC ${sign}${(abs / 1e3).toFixed(0)}K`;
  return `GHC ${sign}${abs.toLocaleString("en-US", { maximumFractionDigits: 0 })}`;
};


