const fmtK = (n) =>
  n >= 1e6
    ? `${(n / 1e6).toFixed(1)}M`
    : n >= 1e3
      ? `${(n / 1e3).toFixed(0)}K`
      : `${n}`;


/* ─── Percent-of-target, capped at 100 ───
   Returns { pct (capped, for display), raw (uncapped, for colour logic),
   exceeded (bool) }. Prevents 6340%-style readouts. */
const pctOfTarget = (actual, target) => {
  if (!target || target <= 0 || actual == null) {
    return { pct: 0, raw: 0, exceeded: false, hasTarget: false };
  }
  const raw = (actual / target) * 100;
  return {
    pct: parseFloat(Math.min(raw, 100).toFixed(1)),
    raw: parseFloat(raw.toFixed(1)),
    exceeded: raw > 100,
    hasTarget: true,
  };
};

/* ─── Weeks elapsed between two dates (floor, min 0) ─── */
const weeksBetween = (from, to) => {
  if (!from || !to || isNaN(from) || isNaN(to)) return 0;
  return Math.max(0, Math.floor((to - from) / (7 * 86400000)));
};

/* Robust Zoho date parser — handles "17-Mar-2026", "2026-04-12", "12-Apr-2026 10:30:00" */
const ZOHO_MONTHS = {
  jan: 0,
  feb: 1,
  mar: 2,
  apr: 3,
  may: 4,
  jun: 5,
  jul: 6,
  aug: 7,
  sep: 8,
  oct: 9,
  nov: 10,
  dec: 11,
};

/* ─── Dedupe helper for subform-flattened Zoho reports ───
   Detailed_* reports return one parent row per subform row, each carrying
   the FULL subform array. Without this every subform loop multi-counts. */
const dedupeById = (records) => {
  if (!Array.isArray(records)) return [];
  const seen = new Set();
  const out = [];
  for (const r of records) {
    const id = String(r?.ID ?? r?.id ?? "");
    if (!id) { out.push(r); continue; }
    if (seen.has(id)) continue;
    seen.add(id);
    out.push(r);
  }
  return out;
};

function parseZohoDate(raw) {
  if (!raw) return null;
  const s = String(raw).trim();
  // "17-Mar-2026" or "17-Mar-2026 10:30:00"
  const m1 = s.match(/^(\d{1,2})-([A-Za-z]{3})-(\d{4})/);
  if (m1) {
    const mo = ZOHO_MONTHS[m1[2].toLowerCase()];
    if (mo !== undefined) {
      const d = new Date(parseInt(m1[3]), mo, parseInt(m1[1]));
      return isNaN(d.getTime()) ? null : d;
    }
  }
  // "2026-04-12" or "2026-04-12T10:30:00"
  const m2 = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (m2) {
    const d = new Date(parseInt(m2[1]), parseInt(m2[2]) - 1, parseInt(m2[3]));
    return isNaN(d.getTime()) ? null : d;
  }
  // "Apr 12, 2026" or "April 12 2026"
  const m3 = s.match(/^([A-Za-z]+)\s+(\d{1,2})[,\s]+(\d{4})/);
  if (m3) {
    const mo = ZOHO_MONTHS[m3[1].slice(0, 3).toLowerCase()];
    if (mo !== undefined) {
      const d = new Date(parseInt(m3[3]), mo, parseInt(m3[2]));
      return isNaN(d.getTime()) ? null : d;
    }
  }
  // fallback
  const d = new Date(s);
  return isNaN(d.getTime()) ? null : d;
}
const addBreed = (map, breed, qty) => {
  if (!breed) return;
  map[breed] = (map[breed] ?? 0) + qty;
};
const isFeedProduct = (name, type) => {
  const u = (name + " " + type).toUpperCase();
  return (
    u.includes("FEED") ||
    u.includes("MASH") ||
    u.includes("PELLET") ||
    u.includes("STARTER") ||
    u.includes("FINISHER") ||
    u.includes("GROWER")
  );
};
const classifyC4uProduct = (productName, productType) => {
  const u = (productName + " " + productType).toUpperCase();
  if (
    u.includes("GRANGER") ||
    u.includes("COCK") ||
    u.includes("LAYER") ||
    u.includes("NOVO") ||
    u.includes("BROILER")
  )
    return "chick";
  if (isFeedProduct(productName, productType)) return "feed";
  if (
    u.includes("MEDIC") ||
    u.includes("VACCINE") ||
    u.includes("DRUG") ||
    u.includes("VITAMIN") ||
    u.includes("ANTIBIOTIC") ||
    u.includes("DEWORM")
  )
    return "medication";
  if (u.includes("DISINFECT") || u.includes("CLEAN") || u.includes("SANITIZ"))
    return "sanitation";
  if (
    u.includes("EQUIP") ||
    u.includes("FEEDER") ||
    u.includes("DRINKER") ||
    u.includes("WATERER") ||
    u.includes("CAGE") ||
    u.includes("LAMP") ||
    u.includes("BULB")
  )
    return "equipment";
  return "other";
};


