  /* ─── Fertility %, batch-matched (same fix pattern as hatchability) ───
     BUG: the old calc divided fertileEggsMonth (fertile eggs from batches
     HATCHED this month) by eggsSetMonth (eggs SET this month) — two
     different sets of batches, since setting→hatching spans ~21 days and
     crosses month boundaries. That mismatch let the ratio exceed 100%.
     Fix: sum each batch's own `set` and `fertile` only for batches whose
     hatch date falls in the requested range — the same batch supplies
     both numerator and denominator, so the ratio can never exceed 100%. */
  function trueFertilityForRange(rangeStart, rangeEnd) {
    let setSum = 0, fertileSum = 0;
    Object.values(hatchBatchMap).forEach((b) => {
      if (!b.hatchedDateRaw || b.fertile <= 0 || b.set <= 0) return;
      if (b.hatchedDateRaw >= rangeStart && b.hatchedDateRaw <= rangeEnd) {
        setSum += b.set;
        fertileSum += b.fertile;
      }
    });
    return setSum > 0 ? parseFloat((Math.min(fertileSum / setSum, 1) * 100).toFixed(1)) : 0;
  }

  const fertilityRate = trueFertilityForRange(monthStart, monthEnd);

  /* ─── Infertile / Clear Eggs — same batch-matched pattern as
     trueHatchForRange / trueFertilityForRange above, so the count always
     reconciles with eggs set (infertile + dead-in-shell + good chicks
     = eggs set for the same completed batches). ─── */
  function trueInfertileForRange(rangeStart, rangeEnd) {
    let setSum = 0, fertileSum = 0;
    Object.values(hatchBatchMap).forEach((b) => {
      if (!b.hatchedDateRaw || b.set <= 0) return;
      if (b.hatchedDateRaw >= rangeStart && b.hatchedDateRaw <= rangeEnd) {
        setSum += b.set;
        fertileSum += b.fertile;
      }
    });
    const infertile = Math.max(0, setSum - fertileSum);
    const pct = setSum > 0 ? parseFloat(((infertile / setSum) * 100).toFixed(1)) : 0;
    return { infertile, pct };
  }

