  const now = new Date().toLocaleString("en-US");
  const curYear  = selectedYear || new Date().getFullYear();
  const prevYear = curYear - 1;

  // ── Filtered hatchery values ─────────────────────────────────────────────
  const eggsSetWk  = hD ? hD.eggsSetWeek  : h.eggsSetWeek;
  const eggsSetMo  = hD ? hD.eggsSetMonth : h.eggsSetMonth;
  const eggsSetYr  = hD ? hD.eggsSetYear  : h.eggsSetYear;
  const goodChkWk  = hD ? hD.goodChicksWeek  : k.goodChicksWeek;
  const goodChkMo  = hD ? hD.goodChicksMonth : k.goodChicksMonth;
  const goodChkYr  = hD ? hD.goodChicksYear  : k.goodChicksYear;
  const hatchPctWk = eggsSetWk > 0 ? parseFloat(((goodChkWk / eggsSetWk) * 100).toFixed(1)) : (hD ? 0 : h.hatchabilityWeek);
  const hatchPctMo = eggsSetMo > 0 ? parseFloat(((goodChkMo / eggsSetMo) * 100).toFixed(1)) : (hD ? 0 : h.hatchabilityMonth);

  // Company-level value (no farm dimension in source data): shown as "—" for a
  // farm that has records and 0 for a farm with none, never the global figure.
  const co = (v) => isFarmFiltered ? (filteredBirdsPlaced > 0 ? "—" : 0) : v;
  const pct2 = (n, d) => d > 0 ? parseFloat(((n / d) * 100).toFixed(2)) : 0;
  // Dead-in-shell figures for the active hatchery scope
  const dsWk = hD ? hD.deadShellWeek  : h.deadShellWeek;
