/* ══════════════════════════════════════════════════
   UI PRIMITIVES
══════════════════════════════════════════════════ */
const Sk = ({ w = "100%", h = 20 }) => (
  <div className="skeleton" style={{ width: w, height: h }} />
);

function Delta({ value, prev }) {
  if (!value || !prev) return null;
  const d = (((value - prev) / prev) * 100).toFixed(1),
    up = d > 0;
  const Ic = up ? ArrowUpRight : ArrowDownRight;
  return (
    <span
      style={{
        fontSize: 10,
        fontWeight: 600,
        padding: "2px 7px",
        borderRadius: 20,
        background: up ? C.greenLt : C.redLt,
        color: up ? C.green : C.red,
        display: "inline-flex",
        alignItems: "center",
        gap: 2,
      }}
    >
      <Ic size={10} />
      {Math.abs(d)}%
    </span>
  );
}

function VsBadge({ current, target, invertColor = false }) {
  if (!target || current == null) return null;
  const t = pctOfTarget(current, target);

  const color = invertColor
    ? (t.raw <= 100 ? C.green : C.red)
    : (t.raw >= 95 ? C.green : t.raw >= 80 ? C.amber : C.red);

  return (
    <span style={{ fontSize: 10, color, fontWeight: 600 }}>
      {t.pct}% of target
      {invertColor
        ? (t.raw <= 100 ? " ✓" : " — over limit")
        : (t.exceeded ? " ✓ met" : "")}
    </span>
  );
}

function Mini({ label, value, sub, subNode, color = C.blue, loading }) {
  const isNA = value === null || value === undefined || value === "null";
  return (
    <div className="mini-card" style={{
      background: C.surf2, border: `1px solid ${C.border}`,
      borderRadius: 10, padding: "12px 14px", opacity: isNA ? 0.55 : 1,
    }}>
      <p style={{
        fontSize: 9, color: C.textSf, fontWeight: 700,
        textTransform: "uppercase", letterSpacing: ".08em", marginBottom: 5,
      }}>{label}</p>
      {loading ? <Sk h={24} /> : (
        <p className="num-rise" style={{
          fontSize: 18, fontWeight: 700,
          color: isNA ? C.textSf : color, fontFamily: C.mono,
        }}>{isNA ? "—" : value}</p>
      )}
      <div style={{ fontSize: 10, color: C.textMd, marginTop: 4 }}>
        {loading ? <Sk h={12} w="60%" />
          : isNA ? <span style={{ fontSize: 9.5, color: C.textSf }}>Not tracked at this filter level</span>
          : (subNode || sub)}
      </div>
    </div>
  );
}


